# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ASLİ DELİLLERİN ÜÇÜNCÜ VE DÖRDÜNCÜ HALKASI: İCMÂ VE KIYAS</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">3. ASLİ DELİL: İCMÂ (الإجماع)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Tanım: Hz. Peygamber\'in (sav) vefatından sonra</text>\n  <text x="45" y="104" font-size="11.2" fill="#1e3a8a">bir asırdaki İslam müçtehitlerinin şer\'î bir</text>\n  <text x="45" y="120" font-size="11.2" fill="#1e3a8a">meselenin hükmü üzerinde görüş birliği etmesidir.</text>\n  <text x="35" y="144" font-size="11.2" fill="#1e3a8a">• Çeşitleri: Sarih (açık) icmâ ve Sükûtî icmâ.</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">• Örnek: Kur\'an-ı Kerim\'in Hz. Ebû Bekir devrinde</text>\n  <text x="45" y="184" font-size="11.2" fill="#1e3a8a">iki kapak arasında Mushaf hâlinde toplanması.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">4. ASLİ DELİL: KIYAS (القياس)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Tanım: Kitap, Sünnet veya İcmâ\'da hükmü açıkça</text>\n  <text x="380" y="104" font-size="11.2" fill="#14532d">bulunmayan bir meselenin hükmünü, aralarındaki</text>\n  <text x="380" y="120" font-size="11.2" fill="#14532d">ortak illet sebebiyle hükmü bilinen meseleye bağlamaktır.</text>\n  <text x="370" y="144" font-size="11.2" fill="#14532d">• Dört Rüknü: 1) Asıl (Makîsün aleyh), 2) Fer\'</text>\n  <text x="380" y="160" font-size="11.2" fill="#14532d">(Makîs), 3) Aslın Hükmü, 4) İllet (Ortak gerekçe).</text>\n  <text x="370" y="184" font-size="11.2" fill="#14532d">• İllet, hükmün konuluşundaki ortak ve açık nedendir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Edille-i Erbaa (Dört Asli Delil): 1. Kitap (Kur\'an)  ⟶  2. Sünnet  ⟶  3. İcmâ  ⟶  4. Kıyas</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FER\'Î (İKİNCİL) DELİLLER VE YÖNTEMLER (FKH.10.2.2)</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#92400e">İSTİHSAN VE MASLAHAT</text>\n  <text x="32" y="88" font-size="10.8" fill="#78350f">• İstihsan: Müçtehidin özel bir</text>\n  <text x="40" y="104" font-size="10.5" fill="#78350f">delil, zaruret veya örf sebebiyle</text>\n  <text x="40" y="120" font-size="10.5" fill="#78350f">genel kıyastan vazgeçip kolaylık</text>\n  <text x="40" y="136" font-size="10.5" fill="#78350f">sağlayan hükme yönelmesidir.</text>\n  <text x="32" y="160" font-size="10.8" fill="#78350f">• Maslahat-ı Mürsele (İstıslah):</text>\n  <text x="40" y="176" font-size="10.5" fill="#78350f">Nasta özel hükmü olmayan konuda</text>\n  <text x="40" y="192" font-size="10.5" fill="#78350f">kamu yararını esas almaktır.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#6b21a8">ÖRF - ÂDET VE SEDD-İ ZERÂİ\'</text>\n  <text x="255" y="88" font-size="10.8" fill="#581c87">• Örf ve Âdet: Toplumun benimse-</text>\n  <text x="263" y="104" font-size="10.5" fill="#581c87">diği, İslam\'ın ilkelerine (nassa)</text>\n  <text x="263" y="120" font-size="10.5" fill="#581c87">aykırı düşmeyen güzel uygulama-</text>\n  <text x="263" y="136" font-size="10.5" fill="#581c87">lar (Örf-i sahih delil kabul edilir).</text>\n  <text x="255" y="160" font-size="10.8" fill="#581c87">• Sedd-i Zerâi\': Haram ve kötülüğe</text>\n  <text x="263" y="176" font-size="10.5" fill="#581c87">götüren yolların ve araçların</text>\n  <text x="263" y="192" font-size="10.5" fill="#581c87">önceden kapatılması ilkesidir.</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#9f1239">DİĞER FER\'Î DELİLLER</text>\n  <text x="478" y="88" font-size="10.8" fill="#881337">• İstıshâb: Aksine bir delil bulun-</text>\n  <text x="486" y="104" font-size="10.5" fill="#881337">madıkça var olan durumun ve</text>\n  <text x="486" y="120" font-size="10.5" fill="#881337">berâet-i zimmetin devam etmesi.</text>\n  <text x="478" y="144" font-size="10.8" fill="#881337">• Sahâbî Kavli: Sahabenin fıkhi</text>\n  <text x="486" y="160" font-size="10.5" fill="#881337">konulardaki içtihat ve fetvaları.</text>\n  <text x="478" y="184" font-size="10.8" fill="#881337">• Şer\'u Men Kablenâ: Önceki</text>\n  <text x="486" y="200" font-size="10.5" fill="#881337">peygamberlerin neshedilmemiş şeriatı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Fer\'î deliller bağımsız kaynaklar olmayıp Kitap ve Sünnetin genel ilkelerine (Mekâsıdü\'ş-Şerîa) dayanır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İÇTİHAT VE MEKÂSIDÜ\'Ş-ŞERİA (ZARÛRİYYÂT-I HAMSE)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">İÇTİHAT, MÜÇTEHİT VE MUKALLİT</text>\n  <text x="35" y="88" font-size="11.2" fill="#064e3b">• İçtihat: Fıkıh âliminin şer\'î-amelî bir meselede</text>\n  <text x="45" y="104" font-size="11.2" fill="#064e3b">delillerden hüküm çıkarmak için tüm gücünü</text>\n  <text x="45" y="120" font-size="11.2" fill="#064e3b">harcamasıdır (Mevrid-i nasta içtihada مساغ yoktur).</text>\n  <text x="35" y="148" font-size="11.2" fill="#064e3b">• Müçtehit: İçtihat ehliyetine sahip فıkıh âlimi.</text>\n  <text x="35" y="172" font-size="11.2" fill="#064e3b">• İftâ / Müftü / Fetva: Sorulan dini meseleye</text>\n  <text x="45" y="188" font-size="11.2" fill="#064e3b">delilleriyle verilen hukuki açıklama ve cevap.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MEKÂSIDÜ\'Ş-ŞERİA (KORUNAN 5 TEMEL DEĞER)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">1. Dinin Korunması (Hıfzu\'d-Dîn)</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">2. Canın / Hayatın Korunması (Hıfzu\'n-Nefs)</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">3. Aklın Korunması (Hıfzu\'l-Akl)</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">4. Neslin ve Ailenin Korunması (Hıfzu\'n-Nesl)</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">5. Malın / Mülkiyetin Korunması (Hıfzu\'l-Mâl)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Fıkhi hükümlerin temel gayesi (Mekâsıdü\'ş-Şerîa), insanların dünya ve ahiret maslahatını (iyiliğini) sağlamaktır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
